export function TextScramblePro({
  phrases = DEFAULT_PHRASES,
  fontSize = 32,
  fontWeight = 400,
  letterSpacing = 0.04,
  fontColor = "#ffffff",
  scrambleColor = "#555555",
  framesPerChar = 10,
  holdDuration = 2200,
  pauseDuration = 400,
  fontFamily = '"Courier New", Courier, monospace',
  textAlign = "center",
  background = "transparent",
  padding = 40,
  revealMode = "left-to-right",
  scrollTrigger = false,
  scrambleOut = true,
  loop = true,
  showCursor = true,
  fadeInDuration = 600,
  className,
  ...props
}) {
  const instanceId = React.useId();
  const [chars, setChars] = React.useState([]);
  const [phraseIndex, setPhraseIndex] = React.useState(0);
  const [started, setStarted] = React.useState(false);
  const [done, setDone] = React.useState(false);
  const [visible, setVisible] = React.useState(false);
  const [cursorOn, setCursorOn] = React.useState(true);

  const containerRef = React.useRef(null);
  const measureRef = React.useRef(null);
  const rafRef = React.useRef(null);
  const timeoutRef = React.useRef(null);

  const [containerWidth, setContainerWidth] = React.useState(0);
  const [scaledFontSize, setScaledFontSize] = React.useState(fontSize);

  const p = React.useRef({ phrases, framesPerChar, holdDuration, pauseDuration, revealMode: revealMode, scrambleOut, loop: loop });
  React.useEffect(() => {
    p.current = { phrases, framesPerChar, holdDuration, pauseDuration, revealMode: revealMode, scrambleOut, loop: loop };
  });

  React.useEffect(() => {
    if (!loop || !done) return;
    const id = setTimeout(() => {
      setDone(false);
      setPhraseIndex(0);
    }, 0);
    return () => clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loop]);

  React.useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => setContainerWidth(el.clientWidth));
    ro.observe(el);
    setContainerWidth(el.clientWidth);
    return () => ro.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const measureEl = measureRef.current;
    if (!measureEl || containerWidth === 0) return;
    const available = containerWidth - padding * 2;
    if (available <= 0) return;
    const natural = measureEl.scrollWidth;
    setScaledFontSize(natural > available ? Math.floor(fontSize * (available / natural)) : fontSize);
  }, [containerWidth, fontSize, padding, phrases]);

  React.useEffect(() => {
    if (!showCursor) return;
    const id = setInterval(() => setCursorOn((v) => !v), 530);
    return () => clearInterval(id);
  }, [showCursor]);

  React.useEffect(() => {
    if (!scrollTrigger) {
      const t = setTimeout(() => {
        setVisible(true);
        setStarted(true);
      }, 50);
      return () => clearTimeout(t);
    }
    const el = containerRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          setStarted(true);
          observer.disconnect();
        }
      },
      { threshold: 0.25 },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [scrollTrigger]);

  const clearTimers = React.useCallback(() => {
    if (rafRef.current != null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
    if (timeoutRef.current != null) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
  }, []);

  const animatePhrase = React.useCallback((target) => {
    if (rafRef.current != null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
    if (timeoutRef.current != null) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }

    const splitChars = target.split("");
    const len = splitChars.length;
    const revealOrder = buildRevealOrder(target, p.current.revealMode);
    const totalFrames = revealOrder.length * p.current.framesPerChar;

    const revealAt = new Array(len).fill(Infinity);
    revealOrder.forEach((ci, i) => {
      revealAt[ci] = i * p.current.framesPerChar;
    });

    const advancePhrase = () => {
      setPhraseIndex((prev) => {
        const next = (prev + 1) % p.current.phrases.length;
        if (!p.current.loop && next === 0) {
          setDone(true);
          return prev;
        }
        return next;
      });
    };

    const runScrambleOut = (order) => {
      const outOrder = [...order].reverse();
      const totalOut = outOrder.length * p.current.framesPerChar;
      const unrevealAt = new Array(len).fill(Infinity);
      outOrder.forEach((ci, i) => {
        unrevealAt[ci] = i * p.current.framesPerChar;
      });
      let outFrame = 0;
      const tickOut = () => {
        setChars(
          splitChars.map((c, i) => {
            if (c === " ") return { char: " ", revealed: true, isSpace: true };
            if (outFrame >= unrevealAt[i]) return { char: randomChar(), revealed: false, isSpace: false };
            return { char: c, revealed: true, isSpace: false };
          }),
        );
        if (outFrame < totalOut) {
          outFrame++;
          rafRef.current = requestAnimationFrame(tickOut);
        } else {
          advancePhrase();
        }
      };
      rafRef.current = requestAnimationFrame(tickOut);
    };

    let frame = 0;
    const tick = () => {
      setChars(
        splitChars.map((c, i) => {
          if (c === " ") return { char: " ", revealed: true, isSpace: true };
          if (frame >= revealAt[i]) return { char: c, revealed: true, isSpace: false };
          return { char: randomChar(), revealed: false, isSpace: false };
        }),
      );
      if (frame < totalFrames) {
        frame++;
        rafRef.current = requestAnimationFrame(tick);
      } else {
        timeoutRef.current = setTimeout(
          () => {
            if (p.current.scrambleOut) runScrambleOut(revealOrder);
            else advancePhrase();
          },
          p.current.holdDuration,
        );
      }
    };

    timeoutRef.current = setTimeout(() => {
      rafRef.current = requestAnimationFrame(tick);
    }, p.current.pauseDuration);
  }, []);

  React.useEffect(() => {
    if (!started || done) return;
    const target = phrases[phraseIndex] ?? "";
    const id = setTimeout(() => {
      setChars(target.split("").map((c) => ({ char: c === " " ? " " : randomChar(), revealed: false, isSpace: c === " " })));
      animatePhrase(target);
    }, 0);
    return () => {
      clearTimeout(id);
      clearTimers();
    };
  }, [phraseIndex, phrases, animatePhrase, clearTimers, started, done]);

  const justifyMap = { left: "flex-start", center: "center", right: "flex-end" };

  return (
    <div
      ref={containerRef}
      data-tsp={instanceId}
      className={`tsp-root ${className ?? ""}`}
      style={{
        background,
        justifyContent: justifyMap[textAlign] ?? "center",
        padding: `0 ${padding}px`,
        opacity: visible ? 1 : 0,
        transition: fadeInDuration > 0 ? `opacity ${fadeInDuration}ms ease` : undefined,
      }}
      {...props}
    >
      <style>{`
        [data-tsp="${instanceId}"].tsp-root {
          position: relative;
          box-sizing: border-box;
          display: flex;
          height: 100%;
          width: 100%;
          align-items: center;
          overflow: hidden;
        }
        [data-tsp="${instanceId}"] .tsp-measure {
          position: absolute;
          pointer-events: none;
          white-space: nowrap;
          visibility: hidden;
        }
        [data-tsp="${instanceId}"] .tsp-text {
          white-space: nowrap;
          user-select: none;
        }
        [data-tsp="${instanceId}"] .tsp-char {
          display: inline-block;
        }
        [data-tsp="${instanceId}"] .tsp-cursor {
          margin-left: 2px;
          display: inline-block;
          transition: opacity 75ms;
        }
        [data-tsp="${instanceId}"] .tsp-demo-panel {
          position: absolute;
          bottom: 20px;
          left: 50%;
          z-index: 100;
          display: flex;
          max-width: calc(100% - 32px);
          transform: translateX(-50%);
          flex-wrap: wrap;
          align-items: center;
          justify-content: center;
          gap: 4px;
          border-radius: 18px;
          border: 1px solid rgba(255, 255, 255, 0.08);
          background: rgba(0, 0, 0, 0.92);
          padding: 10px 8px;
          box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
          backdrop-filter: blur(16px);
          user-select: none;
        }
        [data-tsp="${instanceId}"] .tsp-demo-item {
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 8px;
          padding: 4px 14px;
        }
        [data-tsp="${instanceId}"] .tsp-demo-item-loop {
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 8px;
          padding: 4px 16px;
        }
        [data-tsp="${instanceId}"] .tsp-demo-label {
          font-size: 9px;
          font-weight: 600;
          letter-spacing: 0.12em;
          white-space: nowrap;
          color: rgba(255, 255, 255, 0.38);
          text-transform: uppercase;
        }
        [data-tsp="${instanceId}"] .tsp-reveal-row {
          display: flex;
          gap: 3px;
        }
        [data-tsp="${instanceId}"] .tsp-reveal-btn {
          border-radius: 8px;
          padding: 5px 11px;
          font-size: 11px;
          font-weight: 700;
          white-space: nowrap;
          letter-spacing: 0.04em;
          transition: background-color 150ms, color 150ms;
          border: none;
          cursor: pointer;
          background: rgba(255, 255, 255, 0.08);
          color: rgba(255, 255, 255, 0.5);
        }
        [data-tsp="${instanceId}"] .tsp-reveal-btn-active {
          background: rgba(255, 255, 255, 0.95);
          color: #000;
        }
        [data-tsp="${instanceId}"] .tsp-loop-toggle {
          position: relative;
          height: 24px;
          width: 42px;
          flex-shrink: 0;
          cursor: pointer;
          border-radius: 12px;
          transition: background-color 200ms;
        }
        [data-tsp="${instanceId}"] .tsp-loop-knob {
          position: absolute;
          top: 2px;
          height: 20px;
          width: 20px;
          border-radius: 10px;
          box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
          transition: left 180ms ease-out;
        }
        [data-tsp="${instanceId}"] .tsp-color-label {
          position: relative;
          display: block;
          cursor: pointer;
        }
        [data-tsp="${instanceId}"] .tsp-color-swatch {
          height: 26px;
          width: 26px;
          border-radius: 13px;
          border: 2px solid rgba(255, 255, 255, 0.18);
          box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.3);
        }
        [data-tsp="${instanceId}"] .tsp-color-input {
          position: absolute;
          top: 0;
          left: 0;
          height: 100%;
          width: 100%;
          cursor: pointer;
          border: none;
          padding: 0;
          opacity: 0;
        }
      `}</style>

      <span ref={measureRef} aria-hidden className="tsp-measure" style={{ fontFamily, fontSize, fontWeight, letterSpacing: `${letterSpacing}em` }}>
        {phrases.reduce((a, b) => (a.length >= b.length ? a : b), "")}
      </span>

      <span className="tsp-text" style={{ fontFamily, fontSize: scaledFontSize, fontWeight, lineHeight: 1.4, letterSpacing: `${letterSpacing}em` }}>
        {chars.map((c, i) => (
          <span
            key={i}
            className="tsp-char"
            style={{ color: c.isSpace ? "transparent" : c.revealed ? fontColor : scrambleColor, minWidth: c.isSpace ? `${scaledFontSize * 0.4}px` : undefined }}
          >
            {c.char}
          </span>
        ))}
        {showCursor && (
          <span className="tsp-cursor" style={{ color: fontColor, opacity: cursorOn ? 1 : 0 }}>
            |
          </span>
        )}
      </span>

    </div>
  );
}
